-- Five IPA 2021-06-13 questions checked against the original paper.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q10','exam-fe','反復減算','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問10・改編】自然数x、yについて、q←0、r←xと初期化し、r<yになるまでr←r−y、q←q+1を繰り返す。終了時のq、rはそれぞれ何か。','[{"id":"a","text":"x÷yの余り、x÷yの商"},{"id":"b","text":"x÷yの商、x÷yの余り"},{"id":"c","text":"y÷xの余り、y÷xの商"},{"id":"d","text":"y÷xの商、y÷xの余り"}]','"b"','yを引けた回数qが整数商、残りのrが余りであり、x=qy+r、0≤r<yが成り立つ。 中文：反复减去除数的次数是商，剩余数是余数。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q11','exam-fe','MIPS','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問11・改編】平均命令実行時間が20ナノ秒のコンピュータの性能は何MIPSか。','[{"id":"a","text":"5"},{"id":"b","text":"10"},{"id":"c","text":"20"},{"id":"d","text":"50"}]','"d"','1秒÷20ナノ秒=5,000万命令/秒なので50MIPS。 中文：每秒执行5000万条指令，即50MIPS。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q12','exam-fe','ベースレジスタ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問12・改編】LOAD GR,B,ADはADとベースレジスタBの内容を加えたアドレスの主記憶データをGRに格納する。命令LOAD GR,1,200を実行する。レジスタ1は100、主記憶は番地100→1100、101→1101、200→1200、201→1201、300→1300、301→1301、1200→2200、1201→2201、1300→2300、1301→2301である。GRに入る値はどれか。','[{"id":"a","text":"1201"},{"id":"b","text":"1300"},{"id":"c","text":"2200"},{"id":"d","text":"2300"}]','"b"','有効アドレスは200+100=300。番地300にあるデータ1300を格納する。 中文：有效地址为300，该地址存储的数据是1300。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q13','exam-fe','アドレスバス','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問13・改編】1Mバイトのメモリにバイト単位でアクセスする。1Mバイト=1,024×1,024バイトとして、必要なアドレスバスの信号線は最低何本か。','[{"id":"a","text":"18"},{"id":"b","text":"19"},{"id":"c","text":"20"},{"id":"d","text":"21"}]','"c"','1Mバイトは2^20バイト。バイトごとに一意のアドレスを与えるには20ビットが必要。 中文：1MiB等于2的20次方字节，按字节寻址需要20根地址线。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q16','exam-fe','並列システムの稼働率','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問16・改編】2台のコンピュータを並列に接続し、少なくとも1台が稼働していればシステムは稼働する。各台の故障は独立とする。コンピュータ1のMTBFは480時間、MTTRは20時間、コンピュータ2のMTBFは950時間、MTTRは50時間。システム全体の稼働率は何％か。','[{"id":"a","text":"91.2"},{"id":"b","text":"95.5"},{"id":"c","text":"96.5"},{"id":"d","text":"99.8"}]','"d"','各台の稼働率は480/(480+20)=0.96、950/(950+50)=0.95。両方停止する確率は0.04×0.05=0.002なので全体の稼働率は99.8%。 中文：两台同时故障概率为0.04×0.05，因此整体可用率为99.8%。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q14','exam-fe','デバイスドライバ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問14・改編】デバイスドライバの役割はどれか。','[{"id":"a","text":"アプリケーションからの要求に従い、ハードウェアを直接制御する"},{"id":"b","text":"実行待ちタスクから次に実行するタスクを決める"},{"id":"c","text":"複数ウィンドウの画面表示状態を管理する"},{"id":"d","text":"入力されたコマンドを解釈し対応するプログラムを起動する"}]','"a"','デバイスドライバはハードウェアの制御を担当する。他はスケジューラ、ウィンドウ管理、シェルの役割。 中文：驱动程序控制硬件；其余分别是调度、窗口管理和命令解释。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q15','exam-fe','フェールセーフ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問15・改編】フェールセーフの考え方はどれか。','[{"id":"a","text":"障害発生時にもシステムを安全側に制御する"},{"id":"b","text":"異常時に機能を縮退して運用を継続する"},{"id":"c","text":"重要な構成要素を複数備えて信頼性を高める"},{"id":"d","text":"誰が操作しても誤動作しにくい設計にする"}]','"a"','障害時に安全側へ制御することがフェールセーフ。縮退運転はフェールソフト、誤操作対策はフールプルーフ。 中文：故障时进入安全状态是故障安全；降级运行和防误操作是其他概念。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q17','exam-fe','スプーリング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問17・改編】スプーリング機能の説明はどれか。','[{"id":"a","text":"入出力待ちでCPUが空いたとき別のタスクを実行する"},{"id":"b","text":"実行中のプログラムを中断し制御プログラムへ制御を移す"},{"id":"c","text":"主記憶と低速の入出力装置の間のデータ転送に補助記憶を介し、処理能力を高める"},{"id":"d","text":"主記憶上のバッファプールを使って補助記憶へのアクセス時間を短縮する"}]','"c"','スプーリングは補助記憶を待ち行列として使い、CPU処理と低速装置の処理を分離する。 中文：假脱机借助辅助存储暂存数据，使高速处理和低速外设并行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q18','exam-fe','ページ置換','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問18・改編】仮想記憶のページ置換方式のうち、最後に使われてから最も長時間経過したページを入れ替える方式はどれか。','[{"id":"a","text":"FIFO"},{"id":"b","text":"LFU"},{"id":"c","text":"LIFO"},{"id":"d","text":"LRU"}]','"d"','LRUは最も長く参照されていないページを置換する。FIFOは到着順、LFUは参照回数に基づく。 中文：LRU替换最长时间未使用的页面。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q20','exam-fe','NAND回路','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問20・改編】入力X、YをそれぞれNAND素子の二つの入力に同じ値で接続し、得られた二つの出力を別のNAND素子に入力して出力Zを得る。Zを表す式はどれか。','[{"id":"a","text":"X AND Y"},{"id":"b","text":"X OR Y"},{"id":"c","text":"NOT (X AND Y)"},{"id":"d","text":"NOT (X OR Y)"}]','"b"','最初の2素子でNOT X、NOT Yを生成し、最後にNOT ((NOT X) AND (NOT Y))を得る。ド・モルガンの法則でX OR Y。 中文：前两级分别取反，最后经NAND得到X或Y。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q21','exam-fe','アクチュエータ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問21・改編】アクチュエータの機能として適切なものはどれか。','[{"id":"a","text":"アナログ電気信号をコンピュータが処理できるディジタル信号に変換する"},{"id":"b","text":"キーボードやタッチパネルなどとしてコンピュータに情報を入力する"},{"id":"c","text":"コンピュータから出力された電気信号を力学的な運動に変える"},{"id":"d","text":"物理量を検出して電気信号に変える"}]','"c"','アクチュエータは制御信号を機械的な動きに変える。物理量を電気信号に変えるものはセンサ。 中文：执行器把控制信号转成机械运动；传感器则将物理量转成电信号。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q19','exam-fe','コンパイラ最適化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問19・改編】コンパイラにおける最適化の説明はどれか。','[{"id":"a","text":"オブジェクトコードの代わりにインタプリタ用中間コードを作る"},{"id":"b","text":"コンパイル実行機と異なるアーキテクチャ向けのコードを作る"},{"id":"c","text":"ソースコードを解析し実行時の処理効率を高めたコードを作る"},{"id":"d","text":"実行時に呼出し名や変数値を表示するコードを作る"}]','"c"','最適化は意味を保ちながら実行効率などを改善する。異なる構成向けの生成はクロスコンパイル。 中文：编译优化在保持程序语义的同时改进执行效率；跨架构生成是交叉编译。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
